import { useEffect, useState } from 'react';

function Data({ url }) {
  const [data, setData] = useState(null);
  useEffect(() => {
    const ctrl = new AbortController();
    fetch(url, { signal: ctrl.signal })
      .then((r) => r.json())
      .then(setData)
      .catch((e) => { if (e.name !== 'AbortError') throw e; });
    return () => ctrl.abort();
  }, [url]);
  return <pre>{JSON.stringify(data)}</pre>;
}

