import { useState } from 'react';

function Rename({ initialName }) {
  const [name, setName] = useState(initialName);
  return <input value={name} onChange={(e) => setName(e.target.value)} />;
}

import { useState } from 'react';

function ReadMore({ text, limit = 100 }) {
  const [open, setOpen] = useState(false);
  if (text.length <= limit) return <p>{text}</p>;
  return (
    <p>
      {open ? text : text.slice(0, limit) + '…'}
      <button onClick={() => setOpen((o) => !o)}>{open ? 'less' : 'more'}</button>
    </p>
  );
}

import { useState } from 'react';

function Toppings({ options }) {
  const [chosen, setChosen] = useState([]);
  const toggle = (t) => setChosen((prev) =>
    prev.includes(t) ? prev.filter((x) => x !== t) : [...prev, t]
  );
  return options.map((t) => (
    <label key={t}>
      <input type="checkbox" checked={chosen.includes(t)} onChange={() => toggle(t)} />
      {t}
    </label>
  ));
}

import { useState } from 'react';

function NameField() {
  const [name, setName] = useState('');
  return (
    <input value={name}
      onChange={(e) => setName(e.target.value)}
      onBlur={() => setName((n) => n.trim())} />
  );
}

import { useState, useEffect } from 'react';

function BackToTop() {
  const [show, setShow] = useState(false);
  useEffect(() => {
    const on = () => setShow(window.scrollY > 300);
    window.addEventListener('scroll', on);
    return () => window.removeEventListener('scroll', on);
  }, []);
  if (!show) return null;
  return <button onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}>↑ Top</button>;
}

import { useState } from 'react';

function Phone() {
  const [val, setVal] = useState('');
  const format = (raw) => {
    const d = raw.replace(/\D/g, '').slice(0, 10);
    if (d.length <= 3) return d;
    if (d.length <= 6) return `(${d.slice(0,3)}) ${d.slice(3)}`;
    return `(${d.slice(0,3)}) ${d.slice(3,6)}-${d.slice(6)}`;
  };
  return <input value={val} onChange={(e) => setVal(format(e.target.value))} />;
}

import { useState } from 'react';

function Inputs() {
  const [rows, setRows] = useState([{ id: 1, value: '' }]);
  const update = (id, value) =>
    setRows((prev) => prev.map((r) => r.id === id ? { ...r, value } : r));
  return rows.map((r) => (
    <input key={r.id} value={r.value}
      onChange={(e) => update(r.id, e.target.value)} />
  ));
}

function Square({ children }) {
  return (
    <div style={{ aspectRatio: '1 / 1', background: '#eee' }}>
      {children}
    </div>
  );
}

function SkeletonList({ count = 4 }) {
  return Array.from({ length: count }, (_, i) => (
    <div key={i} style={{ height: 20, margin: 6, background: '#eee', borderRadius: 4 }} />
  ));
}

import { useEffect } from 'react';

function useScrollLock(active) {
  useEffect(() => {
    if (!active) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; };
  }, [active]);
}

function Field({ value }) {
  return <span>{value || '—'}</span>;
}

import { useRef } from 'react';

function AutoTextarea() {
  const ref = useRef(null);
  const grow = () => {
    const el = ref.current;
    el.style.height = 'auto';
    el.style.height = el.scrollHeight + 'px';
  };
  return <textarea ref={ref} onInput={grow} rows={1} style={{ overflow: 'hidden' }} />;
}

function Form({ busy }) {
  return (
    <form>
      <fieldset disabled={busy}>
        <input name="a" />
        <input name="b" />
        <button>Save</button>
      </fieldset>
    </form>
  );
}

import { useRef, useEffect } from 'react';

function usePrevious(value) {
  const ref = useRef();
  useEffect(() => { ref.current = value; }, [value]);
  return ref.current;
}

import { useState } from 'react';

function Quantity() {
  const [qty, setQty] = useState('');
  return (
    <input type="number" value={qty}
      onChange={(e) => setQty(e.target.value)} />
  );
}

function Crumbs({ parts }) {
  return parts.map((p, i) => (
    <span key={p}>
      {i > 0 && <span> / </span>}
      {p}
    </span>
  ));
}

import { useState } from 'react';

function Accordion({ sections }) {
  const [openId, setOpenId] = useState(null);
  return sections.map((s) => (
    <div key={s.id}>
      <button onClick={() => setOpenId((id) => id === s.id ? null : s.id)}>{s.title}</button>
      {openId === s.id && <p>{s.body}</p>}
    </div>
  ));
}

function CopyField({ value }) {
  return (
    <input readOnly value={value}
      onFocus={(e) => e.target.select()} />
  );
}

function Cards({ items }) {
  return (
    <div style={{ display: 'grid', gap: 12, gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))' }}>
      {items.map((x) => <div key={x.id} className="card">{x.name}</div>)}
    </div>
  );
}

function StatusIcon({ status }) {
  const icon = { ok: '✅', warn: '⚠️', error: '❌' }[status] ?? '❓';
  return <span role="img" aria-label={status}>{icon}</span>;
}

